def mini(kind='process'):
    titles={'process':('Process intelligence','Signal overview'), 'batch':('Batch optimisation','Reference profile'), 'maintenance':('Smart maintenance','Equipment health'), 'bottling':('PyBottling','Sequence simulation')}
    title,sub=titles[kind]
    if kind=='maintenance':
        inside='<div class="mini-machine"><i></i><span>Motor M-01</span><b>Normal</b></div><div class="mini-machine warning"><i></i><span>Pump P-203</span><b>Review</b></div><div class="mini-machine"><i></i><span>Drive D-04</span><b>Normal</b></div>'+chart(kind)
    else: inside=chart(kind)
    bottom={'process':[('PROCESS','Monitor'),('PATTERN','Analyse'),('ACTION','Review')],'batch':[('RECIPE','Compare'),('MODEL','Evaluate'),('SETPOINT','Recommend')],'maintenance':[('MODEL','Random Forest'),('ANOMALY','Isolation Forest'),('OUTPUT','Insights')],'bottling':[('01','Fill'),('02','Cap'),('03','Complete')]}[kind]
    return f'<div class="work-art" data-art="{kind}" aria-label="Illustrative {escape(title)} interface"><div class="mini-window"><div class="window-bar"><span>{title.upper()}</span><span class="window-dots"><i></i><i></i><i></i></span></div><div class="mini-top"><span>{sub}</span><small>INTERFACE CONCEPT</small></div>{inside}<div class="mini-bottom">'+''.join(f'<span>{a}<b>{b}</b></span>' for a,b in bottom)+'</div></div></div>'

